import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Insecure name resolution protocols","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/ad/insecure-name-resolution-protocols.md","filePath":"d/ad/insecure-name-resolution-protocols.md","lastUpdated":1781102819000}`),a={name:`d/ad/insecure-name-resolution-protocols.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/ad/insecure-name-resolution-protocols.md for this page in Markdown format</div><h1 id="insecure-name-resolution-protocols" tabindex="-1">Insecure name resolution protocols <a class="header-anchor" href="#insecure-name-resolution-protocols" aria-label="Permalink to “Insecure name resolution protocols”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>An attacker gets into a MitM position if, for example, he is able to manipulate the name resolution in a network. This is the case if an attacker has direct access to the network. The Link-Local Multicast Name Resolution (LLMNR), NetBIOS Name Service (NBT-NS) or Multicast DNS (mDNS) protocols are, in addition to Domain Name System (DNS), three alternative ways of resolving host names in a network.</p><p>Name resolutions via such broadcast protocols can be very easily manipulated by an attacker. An attacker responds to all requests in the network with the address of a system under his control, forcing communication with this system. If the requested host requires authentication, the user name and the Net-NTLMv2 hash are sent to the system controlled by the attacker. Net-NTLMv2 hashes can thus be intercepted and used in the course of relaying attacks.</p><p>An attacker may then be able to access the target system and execute code there. Furthermore, Net-NTLM hashes are susceptible to offline brute force attacks. Attackers can try out password combinations at very high speeds and obtain the plain text password in the event of a successful attack.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><p>Disable LLMNR, NBT-NS, and mDNS name resolutions in the local computer security settings or via Group Policy.</p>`,8)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};